          return {
            name: "vote" as const,
            args: { target_id: cycle === 1 ? 1 : 2, abstain: false },
          };
        throw new Error(`unexpected:${req.context.stage}`);
      },
    };
    await game.phaseManager.runSingleCycle(provider);
