    expect(
      game.phaseManager
        .getEvents()
        .slice(prefix)
        .map((event) => event.type),
    ).not.toContain("wolf_kill_vote_cast");
    for (const type of [
      "gravekeeper_reported",
      "night_resolved",
      "seer_checked",
      "day_speech",
      "vote_cast",
    ])
      expect(
        game.phaseManager
          .getEvents()
          .slice(prefix)
          .some((event) => event.type === type),
      ).toBe(false);
    expect(cancelled).not.toHaveProperty("previousExile");
    await game.phaseManager.runSingleCycle(provider);
    expect(state(game.world).history).toEqual([
      { exileDay: 1, receivedDay: 2, targetId: 1, result: { kind: "camp", camp: "wolf" } },
